[b'--help.txt', b'.draft.txt', b'LOUD.TXT', b'Q3 summary.txt', b'[final] budget.txt', b'archive.txt', b'm*.txt', b'memo.txt', b'notes.md', b'what?.txt']

-- Makefile --
test:
	@bash tests/test_collect.sh

.PHONY: test
